INSERT IGNORE INTO `la_app_version` (`app_code`,`version`,`require_core`,`package_path`,`manifest_json`,`changelog`,`status`,`create_time`) VALUES ('aigc_llm','1.2.1','>=1.0.0','local','{"code":"aigc_llm","name":"AIGC对话","version":"1.2.1","require_core":">=1.0.0","description":"支持自然对话、创作方案、图片视频生成和文档导出的通用创作助手。","changelog":"1. 首页新增通用创作助手，支持自然对话、创作方案、图片、视频、文档、音乐、试衣和文字配音。\\n2. 新增技能配置与技能收藏，支持自定义提示词、展示素材和直接启停。\\n3. 支持上传文档及音视频理解，并按需确认语音转写。\\n4. 完善分阶段回复、话题隔离、连续创作、断线重连和刷新恢复，直接生成无需填写预算。\\n5. 新增跨会话作品库，支持预览、下载、收藏和继续创作，删除与恢复同步到关联素材。","icon":"resource/image/common/menu_generator.png","category":"aigc","cover":"","is_builtin":1,"expire_policy":"allow","sort":880,"frontends":["tenant","pc","uniapp"],"api_prefix":"/app/aigc_llm","platform_menus":"menus/platform.json","menus":"menus/tenant.json","permissions":"permissions/tenant.json","migrations":"migrations","frontend_entries":[{"terminal":"tenant","entry_key":"aigc_llm_admin","name":"AIGC对话","path":"/app/aigc_llm","icon":"el-icon-ChatDotRound","sort":100,"status":1},{"terminal":"pc","entry_key":"aigc_llm","name":"AIGC对话","path":"/app/aigc_llm","icon":"resource/image/common/menu_generator.png","sort":100,"status":1},{"terminal":"uniapp","entry_key":"aigc_llm","name":"AIGC对话","path":"/apps/aigc_llm/pages/index/index","icon":"resource/image/common/menu_generator.png","sort":100,"status":1,"meta":{"pages":[{"name":"对话首页","path":"/apps/aigc_llm/pages/index/index"}]}}]}','1. 首页新增通用创作助手，支持自然对话、创作方案、图片、视频、文档、音乐、试衣和文字配音。
